"""Publish verified boundary findings; preserve original summaries and all inputs."""
import audit as C
import numpy as np,collections,json
O=C.O;R=C.R
def b(x):return x=='True' or x is True
def md(h,rr):return '\n'.join(['|'+'|'.join(h)+'|','|'+'|'.join(['---']*len(h))+'|']+['|'+'|'.join(str(x).replace('|','、') for x in r)+'|' for r in rr])
def main():
 v=C.read(O/'VERIFIED.json');assert v['passed'] and v['D_or_PO_binary_identical_to_existing_column30_on_nonregister_nodes'];rr=C.rows(O/'NODE_BOUNDARIES.csv');cases=C.rows(O/'FIXED_CASES_BOUNDARY_RESULT.csv');group=C.rows(O/'BOUNDARY_GROUP_COUNTS.csv');pc=C.rows(O/'PAIR_SEPARATION_COUNTS.csv');inv=C.rows(O/'CROSS_IMPLEMENTATION_BOUNDARY_UNION.csv');lm={(r['key'],r['row']):r for r in rr}
 counts=[]
 for key in ['orig_train','orig_val','trans_train','trans_val']:
  m=next(r for r in group if r['key']==key and r['scope']=='M_all');p=next(r for r in group if r['key']==key and r['scope']=='positive_payload');h=next(r for r in group if r['key']==key and r['scope']=='positive_hijack');counts.append([key,f"{int(p['D_or_PO'])+int(h['D_or_PO'])}/{int(p['nodes'])+int(h['nodes'])}",f"{m['D_or_PO']}/{m['nodes']}",m['no_output_or_register_boundary'],f"{int(p['no_output_or_register_boundary'])+int(h['no_output_or_register_boundary'])}"])
 caserows=[]
 for r in cases:
  p=lm[r['key'],r['positive_row']];n=lm[r['key'],r['normal_row']];caserows.append([p['source']+' / '+p['parents'],p['flow_full'],n['source']+' / '+n['parents'],p['boundary_signature'],n['boundary_signature'],'可分，但已有PO信息' if b(r['D_SI_PO_diff']) else '此接口仍不能区分'])
 eql=[]
 for key in ['orig_train','orig_val','trans_train','trans_val']:
  r=next(r for r in pc if r['key']==key and r['route']=='all_M' and r['scope']=='feature_equal');eql.append([key,r['pairs'],r['D_SI_PO_diff'],r['distance_diff']])
 invariant=[]
 for key in ['trans_train','trans_val']:
  for side in ['positive','M']:
   z=[r for r in inv if r['key']==key and r['side']==side];invariant.append([key,side,len(z),sum(b(r['first_boundary_union_same']) for r in z),sum(b(r['Donly_PO_same']) for r in z)])
 report=R/'10.15/00_说明/正常对照_固定病例输出用途与DSI边界审计_20261107.md';assert not report.exists()
 doc=['# 固定病例：末端负载、输出用途与D/SI边界审计','', '2026-11-07。复用上一轮冻结的2234个训练/验证节点、1100个已匹配近邻及8个GM固定共同降分/排名受损病例；未重新找候选，未读取测试预测。0模型前向、0训练、0SAT，不改标签、图、特征或原角色表，不引入正例保护。', '', '## 结论', '', '1. **输出用途能描述并分开部分病例，但主要区分已经包含在39维v3中。**原始验证3例、rs232的两个实现病例，可由输出/寄存器边界区分；其余3个变换训练病例中，正负双方都只有悬空组合逻辑，D/SI也分不开。', '2. **D/SI信息确实保存在磁盘，当前检测器没有消费。**但本轮2232个非寄存器节点中，“仅允许D依赖跨寄存器后能否到达PO”，以及“第一寄存器边界前能否到PO或D”，都与已有第30列PO距离的可达性完全一致。补接D/SI接口是语义完整性改进，不能据此声称已找到本轮无收益的主要原因或保证AP增益。', '3. **根39维完全相同的固定正负配对，D/SI/PO类型与最短边界距离也全部相同。**没有发现靠新增这些字段即可解决这批摘要重叠的证据。', '4. 更值得推进的是“源门在变换后由哪些有效信号/区域承载”：部分制造正例实际落在闭合悬空分支。需要审计同源功能承载对应，不直接改标签，也不能称当前图构建错误或这些正标签已经被证伪。', '', '## 1. 边界定义与正确性', '', '以现有有向图和当前网表实际引脚为准，从根沿组合后继走到首个寄存器，分别记录D、SI、时钟、复位、使能等目的引脚；同时记录首个寄存器之前遇到的真正PO驱动点。遇到寄存器即停止，不把从SI进入后又沿Q离开的路径当作组合功能路径。', '', '另计算“仅D依赖跨寄存器的结构PO路径”：保留组合边及目的寄存器D边，排除SI/时钟/复位/使能作为数据依赖后，允许沿寄存器节点继续走向PO。它仍是结构可达性，不含时序初始化、扫描模式、MUX条件敏化或SAT影响证明，不能替代实际功能判定。', '', '末端负载区分两层：根本身无后继且不是PO，或根经若干组合门后整个后继分量都没有PO/任何寄存器输入。只看根扇出0会漏掉后一类。对固定病例中11个无边界端点已保存完整闭合分量证书（节点、引脚、后继、末端、源文件哈希），证实没有边跳出分量，且不存在PO或寄存器。两个寄存器根节点保留记录，但不进入组合根对比。', '', f"独立网表解析核对了{v['independent_views']}个视图、{v['actual_pin_role_checks']:,}条连接的实际目的引脚角色，并与保存图及edge_roles逐条一致；另由保存边与角色反向重算{v['independent_distance_checks']}项距离，通过。本轮未发现这些固定图的边/引脚角色不一致。", '', '## 2. 哪些已进模型，哪些没有', '', md(['信息','当前保存/消费情况','解释边界'],[['真正PO驱动距离','39维第30列，归一化后已消费','原图路径可穿过各种寄存器输入；不是条件功能影响'],['一般寄存器距离及二跳上下文','第33至36列，已消费','register_reset指在寄存器处重置距离，不等于复位引脚类型；不区分D/SI'],['D/SI/CLK/RESET/ENABLE目的角色','edge_roles位1/4/2/8/16已保存','torch_graph只返回x、edge、y；当前模型未接收角色'],['末端负载/后继用途','扇出、距离和PO标记有部分摘要','未显式提供完整悬空分量或首边界用途'],['下游信息传播','GIN默认source_to_target，根聚合入向消息','下游用途主要靠根摘要反映；不能把“有边”当成根已聚合下游表示'],['MUX数据/选择端及Q/QN相位','原网表可见，普通组合edge_roles统一为1','当前检测器没有显式消费这些引脚身份/输出相位']]), '', '接口缺口真实存在，但是否值得训练接入要看它能否为固定反例增加区分。本轮的存在性/最短距离结果没有支持直接据此开训练。', '', '## 3. 固定节点总体：可观测用途与制造标签并不重合', '', '下表分子为“能在首寄存器前到达PO或D”的结构可达节点；载荷/劫持为纯制造来源，混合来源单列，未提升或撤销任何可信标签。', '', md(['范围','真实载荷/劫持：有PO或D / 总数','M：有PO或D / 总数','M无任何输出/寄存器边界','真实载荷/劫持无任何边界'],counts), '', '训练实际曝光M中，原始9/93、变换22/173仍具有PO或D用途；正常逻辑本来也可以有输出用途，因此不能把“有PO/D”当木马标签。原始训练的22个有用途M来自四个a4ctlequiv正常源；变换侧还包含其他制造源与优化后的用途变化。', '', '验证M全部无边界，部分源于当前制造配方构成，不能将该分布上的良好区分外推为一般正常逻辑均悬空。变换训练40个载荷后代无边界，涉及13个独立源、22个源门对象；验证9个涉及5个源、9个源门对象。这是保留的制造来源标签与当前节点结构用途之间的差别，不是本轮重判标签。', '', '## 4. 八个固定共同降分病例：哪些真正被分开', '', md(['正例来源 / 源门','完整流程','近邻M来源 / 源门','正例用途','M用途','本轮结果'],caserows), '', 'DEAD表示存在悬空末端且无PO或任何寄存器边界；PO/D可同时出现，因为输出信号也可能被寄存器D消费。上述表不按分数重新选近邻。', '', '5/8节点可由边界用途区分，但这5例原来的PO距离已经为正例可达、M不可达。也就是说，它们更像是现有信息没有被模型稳定用于排序，而不是缺少PO特征。rs232的keepcur/keepnone是同一源门的两个实现，不能当两次独立实验。', '', '其余3例无法区分：s15850 delta的DP2（行366920，闭合3节点）、DP0（行372335，闭合2节点），以及s35932 alpha的AP2（行983350，根本身为悬空末端）。目标节点的名字/父门制造角色正确传递，并不意味着该物理后代仍承载原门的可观测功能。DP2/DP0同一视图内本轮已审计的其他同父门正例也均为DEAD；这尚不能保证已经找到该源门在变换后的全部有效功能表示。', '', '### 对完全相同39维的配对，D/SI是否增加信息', '', md(['范围，全M固定近邻路线','根39维相同配对','D/SI/PO存在性不同','首边界最短距离不同'],eql), '', '这些配对的D/SI端点数、PO端点数及根是否末端也都相同；变换训练仅1对的悬空末端数量/访问组合节点数不同，不能据此形成稳定分类规则。新增更细的端点身份或输入函数仍可能有价值，但本轮没有验证其预测增益，也不应将网表名、寄存器实例名当可迁移特征。', '', '## 5. 跨实现是否稳定', '', '对同一源门，把该视图内已冻结审计后代的D/SI/PO用途取并集，与原始源门比较。这里的集合不保证覆盖源门全部功能承载；混合来源与多父门记录不强做一对一。', '', md(['范围','侧别','源门×实现记录','D/SI/PO并集一致','仅D路径PO可达性一致'],invariant), '', '边界标签并非逐门完全不变；在优化、拆分、合并、别名和功能吸收后，保留的源名后代可能用途改变。不能将当前用途签名直接当作所有实现都必须继承的角色标签或新等价一致性目标。需要按独立源门/后代集合报告，不把1486条记录当独立电路样本。', '', '## 6. 下一步建议', '', '暂不因为edge_roles未接入就追加训练。优先固定上表3个DEAD正例，利用已有信号对应、区域对应及证明，追踪原生源门输出与变换后仍有PO/D用途的实际承载信号，明确是逻辑被吸收/合并、保留冗余副本，还是现有节点血缘只覆盖了名字后代。允许记录无法确认，不新增大规模SAT，不直接给现有proved状态背书。', '', '对已有PO信息足以区分的5例，可继续复用预测，分开核对“结构有用途”和“已有分数/排序是否利用它”；单凭输出路径存在不能推断功能安全角色。所有制造来源标签继续用于原合同主AP；可另外建立边界资格诊断表，但不得悄悄删正例、降低其损失权重或引入正例保护。', '', '只有当新的角色/边界字段能在固定训练与验证反例上增加信息，并按同源对象确认跨实现可用后，再拟单因素输入接入合同。当前证据不支持“增加D/SI就能解决39维重叠”，也不支持“真实载荷均可由用途规则替代模型识别”。', '', '## 证据位置', '', '`_p0pilot/control_boundary_use_20261107/`：`NODE_BOUNDARIES.csv`、`PATH_WITNESSES.csv`、`VIEW_PIN_CHECKS.csv`、`MODEL_INFORMATION_AUDIT.csv`、`BOUNDARY_GROUP_COUNTS.csv`、`BOUNDARY_PER_SOURCE.csv`、`FROZEN_PAIR_BOUNDARY_CONTRASTS.csv`、`PAIR_SEPARATION_COUNTS.csv`、`FIXED_CASES_BOUNDARY_RESULT.csv`、`CROSS_IMPLEMENTATION_BOUNDARY_UNION.csv`、`DEAD_COMPONENT_CERTIFICATES.json`、`INDEPENDENT_DISTANCE_CHECKS.csv`、`VERIFIED.json`。','']
 text='\n'.join(doc);expected=None
 for line in text.splitlines():
  if line.startswith('|'):n=len(line.split('|'));assert expected in [None,n],line;expected=n
  else:expected=None
 report.write_text(text,encoding='utf-8')
 entry='''\n\n## 2026-11-07 固定病例输出用途与D/SI边界审计\n\n本轮复用2234训练/验证节点、1100固定近邻与8个共同降分病例；0模型前向、0训练、0SAT，不改标签/特征/图，不引入正例保护。详见[报告](正常对照_固定病例输出用途与DSI边界审计_20261107.md)及`_p0pilot/control_boundary_use_20261107/VERIFIED.json`。\n\n- 独立核对275视图、2,491,361条实际目的引脚角色连接，与保存图/edge_roles一致；反向重算8928项距离。固定无边界端点11个闭合分量证书通过，本轮未发现固定图的连接/引脚角色错误。\n- edge_roles的D/SI等角色已保存，但当前检测模型只接收x/edge/y，未消费角色；39维第30列PO距离、第33至36列一般寄存器摘要已消费。一般寄存器距离不区分D/SI，普通组合边也不区分MUX数据/选择端、Q/QN输出相位。\n- 8个固定病例中，原始验证3例及rs232两个实现病例可由PO/D用途分开，但已有PO距离已包含这一区分；另外3个变换训练正例与M均只有悬空后继，D/SI也不能分开。两个rs232实现仍是同一源门对象，不作独立实验。\n- 在2232个非寄存器根上，仅D依赖跨寄存器的PO可达性、以及首边界前PO或D存在性，与旧第30列可达性完全一致；根39维完全相同的配对，D/SI/PO存在性和最短距离也全相同。不能以接口未接入直接推断新增字段可提高AP。\n- 当前纯载荷/劫持后代中，变换训练40个（13源/22源门对象）、验证9个（5源/9源门对象）无任何PO/寄存器边界；记录制造标签与当前用途差别，不改正标签。正常M也可有PO/D用途，不能用用途规则替代安全标签。\n- 下一步优先复用已有信号/区域对应与证明，追踪delta DP2/DP0、alpha AP2三个DEAD病例的有效功能承载，区分吸收/合并/冗余副本与仅名字血缘覆盖；暂不因此追加训练或SAT，不降低正例权重。\n'''
 backups={}
 for name in ['SAT作用证明.md','SAT工作总结.md']:
  p=report.parent/name;old=p.read_bytes();backup=O/(name+'.before_boundary_use');assert not backup.exists();backup.write_bytes(old);p.write_bytes(old+entry.replace('\n','\r\n').encode('utf-8'));assert p.read_bytes().startswith(old);backups[str(p.relative_to(R))]=dict(original_sha=C.sha(backup),updated_sha=C.sha(p),prefix_preserved=True)
 for name,h in {**C.read(O/'AUDIT_COMPLETE.json')['protected_inputs'],**v['protected_local_runtime']}.items():assert C.sha(R/name)==h,name
 manifest={str(p.relative_to(O)):C.sha(p) for p in O.rglob('*') if p.is_file() and p.suffix!='.pyc' and p.name not in ['OUTPUT_MANIFEST.json','PUBLISHED.json']};(O/'OUTPUT_MANIFEST.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8');(O/'PUBLISHED.json').write_text(json.dumps(dict(passed=True,report=str(report),report_sha=C.sha(report),summary_backups=backups,manifest_files=len(manifest),model_forward=0,training=0,SAT=0),ensure_ascii=False,indent=2),encoding='utf-8');print('PUBLISHED',len(manifest))
if __name__=='__main__':main()
